SELECT p.gender, CAST(COUNT(DISTINCT CASE WHEN p.dod IS NOT NULL THEN p.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT p.subject_id), 0) AS mortality_rate, CAST(COUNT(DISTINCT CASE WHEN p.diagnoses_icd.icd_code = '24484000' THEN p.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT p.subject_id), 0) AS ards_rate, percentile_cont(0.75) within GROUP (ORDER BY i.los) AS q3_los FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id WHERE p.gender = 'F' AND p.anchor_age >= 40 AND p.anchor_age <= 50 AND p.diagnoses_icd.icd_code = '35213000' GROUP BY p.gender ORDER BY mortality_rate DESC, ards_rate DESC, q3_los DESC;